import express from "express";
import { fileURLToPath } from "node:url";
import {
  connectDB,
  getAllEmployees,
  findEmployeesByDepartment,
  findEmployeesByMinSalary,
  getTopThreeEarners,
  addEmployee,
} from "./database.js";

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(fileURLToPath(new URL("./public", import.meta.url))));

function sendList(res, data, functionName) {
  if (!Array.isArray(data)) {
    return res.status(500).json({
      error: `${functionName}() did not return a list from the database. Complete it in database.js.`,
    });
  }
  res.json(data);
}

app.get("/api/employees", async (req, res) => {
  try {
    sendList(res, await getAllEmployees(), "getAllEmployees");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/employees/search", async (req, res) => {
  try {
    sendList(res, await findEmployeesByDepartment(req.query.department), "findEmployeesByDepartment");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/employees/filter", async (req, res) => {
  const minSalary = Number(req.query.minSalary);
  if (Number.isNaN(minSalary)) {
    return res.status(400).json({ error: "Please enter a number." });
  }
  try {
    sendList(res, await findEmployeesByMinSalary(minSalary), "findEmployeesByMinSalary");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/employees/top", async (req, res) => {
  try {
    sendList(res, await getTopThreeEarners(), "getTopThreeEarners");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post("/api/employees", async (req, res) => {
  try {
    const saved = await addEmployee(req.body);
    if (!saved) {
      return res.status(500).json({
        error: "addEmployee() did not return the saved employee. Complete it in database.js.",
      });
    }
    res.status(201).json(saved);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

try {
  await connectDB();
} catch (err) {
  console.log("Could not connect to MongoDB:", err.message);
}

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
